changeSet.sql:
update
    COMPONENT_CONFIG as q1,
    (
        select
            cf.id,
            @path_to_name := json_unquote(json_search(value, 'one', 'firstName', null, '$.attributes[*].name')) as path_to_name,
            @path := concat(trim (trailing '.name' from @path_to_name), '.required.roles') as path,
            @new_value := json_set(value, @path, json_array('admin', 'user')) as new_value
        from COMPONENT_CONFIG cf
        join COMPONENT c on c.ID = cf.COMPONENT_ID
        join REALM r on r.ID = c.REALM_ID
        where cf.NAME = 'kc.user.profile.config' and r.NAME in ('user', 'ER-TELECOM', 'S-TELECOM')
    ) as q2
set q1.value = q2.new_value
where q1.id = q2.id;

update
    COMPONENT_CONFIG as q1,
    (
        select
            cf.id,
            @path_to_name := json_unquote(json_search(value, 'one', 'lastName', null, '$.attributes[*].name')) as path_to_name,
            @path := concat(trim(trailing '.name' from @path_to_name), '.required') as path,
            @new_value := json_remove(value, @path) as new_value
        from COMPONENT_CONFIG cf
        join COMPONENT c on c.ID = cf.COMPONENT_ID
        join REALM r on r.ID = c.REALM_ID
        where cf.NAME = 'kc.user.profile.config' and r.NAME in ('user', 'ER-TELECOM', 'S-TELECOM')
    ) as q2
set q1.value = q2.new_value
where q1.id = q2.id;


