UPDATE SETTINGS SET VALUE = '<p> Мы не храним ваши пароли.<br /> Если вы забыли свой пароль или у вас не получается войти в Личный кабинет — воспользуйтесь формой восстановления пароля по ссылке <a class="no_block" href="{0}">«Забыли пароль?»</a>. </p> <div class="instruction"> <p class="instruction_text"> <span class="mark">&nbsp;</span> Для восстановления данных укажите ваш логин. </p> <p class="instruction_text"> <span class="mark">&nbsp;</span> На ваш адрес электронной почты будет отправлена ссылка для восстановления пароля.<br /> <span style="margin-left: 19px">Срок действия ссылки {7}.</span> </p> </div>' WHERE EXT_ID = 'emailPasswordFooterHtml';
